// ?copyAt@Rva002060B0Owner@@QBEXPAURva002060B0Triple@@H@Z
// Retail selects one of the owner's vector records or its fallback record,
// then copies three words to the caller's output record.

struct Rva002060B0Triple
{
	void copyTo(Rva002060B0Triple *destination) const
	{
		destination->m_a = m_a;
		destination->m_b = m_b;
		destination->m_c = m_c;
	}

	int m_a;
	int m_b;
	int m_c;
};

class Rva002060B0Value
{
public:
	Rva002060B0Triple &triple() { return m_triple; }

	char m_pad[8];
	Rva002060B0Triple m_triple;
};

class Rva002060B0Fallback
{
public:
	Rva002060B0Triple &triple() { return m_triple; }

	char m_pad[0x38];
	Rva002060B0Triple m_triple;
};

class Rva002060B0Vector
{
public:
	int size() const { return m_end - m_begin; }

	Rva002060B0Value **m_begin;
	Rva002060B0Value **m_end;
};

class Rva002060B0Owner
{
public:
	void copyAt(Rva002060B0Triple *out, int index) const;

	char m_pad0[8];
	Rva002060B0Fallback *m_fallback;
	char m_padC[0x24 - 0x0C];
	Rva002060B0Vector m_values;
};

void Rva002060B0Owner::copyAt(Rva002060B0Triple *out, int index) const
{
	const Rva002060B0Triple *source;
	if (index >= 0 && (unsigned int)index < (unsigned int)m_values.size())
		source = &m_values.m_begin[index]->m_triple;
	else
		source = &m_fallback->m_triple;

	volatile Rva002060B0Triple *destination = out;
	source->copyTo((Rva002060B0Triple *)destination);
}
